import sys

class N:
    __slots__ = ('v', 'nxt')
    def __init__(self, v=0, nxt=None):
        self.v = v; self.nxt = nxt

def to_list(head):
    out = []
    cur = head
    while cur:
        out.append(cur.v)
        cur = cur.nxt
    return out

def add_best(a, b):
    def helper(i, j, carry):
        x = a[i] if i < len(a) else 0
        y = b[j] if j < len(b) else 0
        if i >= len(a) and j >= len(b) and not carry:
            return None
        s = x + y + carry
        carry, d = divmod(s, 10)
        return N(d, helper(i + 1, j + 1, carry))
    return to_list(helper(0, 0, 0))

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    nA = int(data[0])
    a = list(map(int, data[1:1 + nA]))
    idx = 1 + nA
    nB = int(data[idx]); idx += 1
    b = list(map(int, data[idx:idx + nB]))
    print(' '.join(map(str, add_best(a, b))))
